{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/delivery-info.json
    How delivery works: the facts as icon cards, then the zones with their time and the order that ships free. Axes: layout (full: facts over zone cards, facts: the facts only, split: the facts beside a list of zones), tone, density.
    Props (p): id, title, lead, facts, zones, labels, layout, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_facts = ($p['facts'] ?? null)}
{var $v_zones = ($p['zones'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'full')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_17}
  {capture $c_16}
    {capture $c_6}
      {foreach ui_l($v_facts) as $v_f}
        {capture $c_5}
          {capture $c_1}
            {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_f, ['icon'])), 'Size' => 20]])|noescape}
          {/capture}
          {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex size-10 shrink-0 items-center justify-center rounded bg-muted'], 'children' => $c_1])|noescape}
          {capture $c_4}
            {capture $c_2}
              {=ui_text(ui_get($v_f, ['title']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_2])|noescape}
            {capture $c_3}
              {=ui_text(ui_get($v_f, ['text']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_3])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2'], 'children' => $c_4])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Class' => 'rounded bg-card inset-ring inset-ring-border p-6', 'Attrs' => ui_attrs(['data-testid', 'fact'])], 'children' => $c_5])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_layout, 'split')) ? '1-2' : '1-4')), 'Class' => 'gap-4', 'Attrs' => ui_attrs(['data-testid', 'facts'])], 'children' => $c_6])|noescape}
    {if ui_t(!(ui_eq($v_layout, 'facts')))}
      {capture $c_15}
        {capture $c_7}
          {=ui_text(ui_get($v_labels, ['zones']))}
        {/capture}
        {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'lg', 'Weight' => 'bold'], 'children' => $c_7])|noescape}
        {capture $c_14}
          {foreach ui_l($v_zones) as $v_z}
            {capture $c_13}
              {capture $c_10}
                {capture $c_8}
                  {=ui_text(ui_get($v_z, ['name']))}
                {/capture}
                {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_8])|noescape}
                {capture $c_9}
                  {=ui_text(ui_get($v_z, ['time']))}
                {/capture}
                {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'secondary', 'Size' => 'default'], 'children' => $c_9])|noescape}
              {/capture}
              {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'baseline', 'Justify' => 'between'], 'children' => $c_10])|noescape}
              {capture $c_11}
                {=ui_text(ui_get($v_z, ['area']))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_11])|noescape}
              {capture $c_12}
                {=ui_text(ui_tpl(ui_get($v_labels, ['freeFrom']), [ui_money(ui_get($v_z, ['freeFrom']), ui_get($v_z, ['currency']))]))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'medium'], 'children' => $c_12])|noescape}
            {/capture}
            {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Class' => ui_s((ui_t(ui_eq($v_layout, 'split')) ? 'border-b border-border pb-4' : 'rounded bg-card inset-ring inset-ring-border p-6')), 'Attrs' => ui_attrs(['data-testid', 'zone'])], 'children' => $c_13])|noescape}
          {/foreach}
        {/capture}
        {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_layout, 'split')) ? 'flex flex-col gap-4' : 'grid grid-cols-1 gap-4 md:grid-cols-3'))], 'children' => $c_14])|noescape}
      {/capture}
      {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch'], 'children' => $c_15])|noescape}
    {/if}
  {/capture}
  {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s(ui_cnv(['grid grid-cols-1 gap-8', (ui_t(ui_eq($v_layout, 'split')) ? 'items-start md:grid-cols-2' : '')]))], 'children' => $c_16])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_17])|noescape}
